sql_query:
SELECT "Control arm"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Control arm", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Pembrolizumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control arm" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Control arm", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Pembrolizumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_control_category(source_value) AS "control_category"
FROM base;
